import java.util.*;

public class Main {
    static long A;
    static int count = 0;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        A = sc.nextLong();
        for (long i = 1; i * i <= A; i++) {
            if (A % i == 0) {
                check(i);
                if (i != A / i) check(A / i);
            }
        }
        System.out.println(count);
    }

    static void check(long d) {
        if (d == 1) {
            count++;
            return;
        }
        for (long i = 1; i * i <= d; i++) {
            if (d % i == 0) {
                long j = d / i;
                if (gcd(i, j) == 1) {
                    count++;
                }
            }
        }
    }

    static long gcd(long a, long b) {
        while (b != 0) {
            long t = b;
            b = a % b;
            a = t;
        }
        return a;
    }
}
